// ============================================================
//  Accept a scan from MQTT, HTTP or the simulate button, clean
//  it up, and swallow contact bounce.
//
//  NOTE: this only removes the same card re-reading itself within
//  a few seconds. Whether a tap is an arrival, a late arrival, a
//  departure or a pointless repeat is decided later, in "classify tap".
// ============================================================
const BOUNCE_MS = 8000;

let p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = { uid: p }; }
}

const uid = String(p.uid || '').toUpperCase().replace(/[^0-9A-F]/g, '');
if (!uid) {
    node.warn('Scan received with no usable UID: ' + JSON.stringify(p));
    return null;
}

// Trust the ESP32 clock only if NTP actually synced.
let when = new Date();
if (p.timestamp) {
    const t = new Date(p.timestamp);
    if (!isNaN(t.getTime())) { when = t; }
}

const seen = flow.get('bounce') || {};
const key  = uid + '@' + (p.device || 'unknown');
if (seen[key] && (Date.now() - seen[key] < BOUNCE_MS)) {
    node.status({ fill: 'grey', shape: 'ring', text: 'bounce ignored' });
    return null;
}
seen[key] = Date.now();
flow.set('bounce', seen);

msg.scan = { uid: uid, device: p.device || 'unknown', when: when };
return msg;

// ============================================================
//  Match the UID against the student registry.
// ============================================================
const db  = global.get('students') || {};
const rec = db[msg.scan.uid] || null;

msg.student = rec;

const d   = msg.scan.when;
const pad = function (n) { return String(n).padStart(2, '0'); };
msg.fmt = {
    date: d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()),
    time: pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds())
};

if (!rec) {
    msg.result = 'unknown';
    node.status({ fill: 'red', shape: 'dot', text: msg.scan.uid + ' -> unknown' });
}
return msg;

// =====================================================================
//  CLASSIFY THE TAP  -  arrival, late arrival, departure or repeat?
//
//  All times come from school-calendar.json (global.calendar), so the
//  school day is edited in ONE place and both tabs agree.
//
//      classStart   "08:00"   when the class begins
//      graceSeconds  600      tap within this of classStart = on time
//                             (set to 10 for a live demo)
//      classEnd     "13:00"   from here on, a tap means going home
//
//  The rule is deliberately state-first, not clock-first:
//    no IN recorded yet          -> this tap is the ARRIVAL, however late
//    has IN, no OUT, after end   -> this tap is the DEPARTURE
//    anything else               -> a repeat tap, acknowledged but not logged
// =====================================================================
if (msg.result === 'unknown') { return msg; }

const cal   = global.get('calendar') || {};
const START = cal.classStart   || '08:00';
const END   = cal.classEnd     || '13:00';
const GRACE = (typeof cal.graceSeconds === 'number') ? cal.graceSeconds : 600;

function atClock(sample, hhmm) {
    const parts = String(hhmm).split(':');
    const d = new Date(sample.getTime());
    d.setHours(parseInt(parts[0], 10) || 0,
               parseInt(parts[1], 10) || 0,
               parseInt(parts[2], 10) || 0, 0);
    return d;
}

const when        = msg.scan.when;
const classStart  = atClock(when, START);
const onTimeUntil = new Date(classStart.getTime() + GRACE * 1000);
const classEnd    = atClock(when, END);

// --- today's per-student state (reset automatically at midnight) ---
let state = flow.get('todayTaps') || {};
if (state.date !== msg.fmt.date) { state = { date: msg.fmt.date, byUid: {} }; }
const rec = state.byUid[msg.scan.uid] || {};

let direction, status;

if (!rec.in) {
    direction = 'IN';
    status    = (when.getTime() <= onTimeUntil.getTime()) ? 'ON_TIME' : 'LATE';
    rec.in    = msg.fmt.time;
    rec.inStatus = status;
    msg.result = (status === 'LATE') ? 'in_late' : 'in_ontime';

} else if (!rec.out && when.getTime() >= classEnd.getTime()) {
    direction  = 'OUT';
    status     = 'OUT';
    rec.out    = msg.fmt.time;
    msg.result = 'out';

} else {
    direction  = rec.out ? 'OUT' : 'IN';
    status     = 'REPEAT';
    msg.result = 'duplicate';
}

state.byUid[msg.scan.uid] = rec;
flow.set('todayTaps', state);

msg.tap = {
    direction:   direction,
    status:      status,
    classStart:  START,
    classEnd:    END,
    onTimeUntil: onTimeUntil.toTimeString().substring(0, 8),
    minutesLate: (status === 'LATE')
        ? Math.round((when.getTime() - classStart.getTime()) / 60000) : 0,
    arrivedAt:   rec.in  || '',
    leftAt:      rec.out || ''
};

node.status({
    fill:  (msg.result === 'in_ontime') ? 'green'
         : (msg.result === 'in_late')   ? 'yellow'
         : (msg.result === 'out')       ? 'blue' : 'grey',
    shape: 'dot',
    text:  msg.student.name + ' -> ' + msg.result
});
return msg;

// One CSV line per real event. Repeat taps are never logged.
// Column order must match the header:
//   Date,Time,StudentID,Name,Class,UID,Device,Direction,Status
const s = msg.student;
const f = msg.fmt;
const q = function (v) {
    return '"' + String(v === null || v === undefined ? '' : v).replace(/"/g, '""') + '"';
};

msg.payload = [
    q(f.date), q(f.time), q(s.studentId), q(s.name), q(s.className),
    q(msg.scan.uid), q(msg.scan.device), q(msg.tap.direction), q(msg.tap.status)
].join(',');
return msg;

// ============================================================
//  Parent notification. One builder, four kinds of message.
//  Token lives on the flow tab -> Environment -> TELEGRAM_BOT_TOKEN.
// ============================================================
const TOKEN = env.get('TELEGRAM_BOT_TOKEN');
if (!TOKEN) {
    node.warn('TELEGRAM_BOT_TOKEN is not set - notification skipped');
    return null;
}

const s = msg.student;
if (!s.parentChatId) {
    node.warn('No parentChatId for ' + s.name + ' - notification skipped');
    return null;
}

const t    = msg.tap;
const name = s.name + ' (' + s.studentId + ')';

// Was this child reported absent earlier today? If so the parent has already had a
// worrying message, and whatever we send now must visibly close that off -- whether
// they turned up on time after a reader glitch, or genuinely turned up late.
const alerted = global.get('absenceAlerted') || {};
const ids     = alerted.ids || [];
const wasReportedAbsent = (alerted.date === msg.fmt.date) &&
                          (ids.indexOf(s.studentId) !== -1);

let text;

if (msg.result === 'out') {
    text = 'Left school\n\n' + name + ' was recorded leaving at ' + msg.fmt.time +
           ' on ' + msg.fmt.date + '.' +
           (t.arrivedAt ? '\nArrived: ' + t.arrivedAt : '');

} else if (wasReportedAbsent) {
    // Clears the earlier alarm, and only fires once.
    text = 'Update: ' + s.name + ' has now arrived at school at ' + msg.fmt.time + '.';
    if (msg.result === 'in_late') {
        text += '\nRecorded as LATE - class started at ' + t.classStart +
                ' (' + t.minutesLate + ' minute(s) late).';
    }
    text += '\nPlease disregard the earlier absence notice.';
    global.set('absenceAlerted', {
        date: alerted.date,
        ids:  ids.filter(function (id) { return id !== s.studentId; })
    });

} else if (msg.result === 'in_late') {
    text = 'LATE ARRIVAL\n\n' + name + ' arrived at ' + msg.fmt.time +
           ' on ' + msg.fmt.date + '.\nClass started at ' + t.classStart +
           ' - ' + t.minutesLate + ' minute(s) late.';

} else {
    text = 'Arrived at school\n\n' + name + ' arrived at ' + msg.fmt.time +
           ' on ' + msg.fmt.date + '.';
}

msg.url     = 'https://api.telegram.org/bot' + TOKEN + '/sendMessage';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { chat_id: s.parentChatId, text: text };
return msg;

// OPTIONAL: mirror the row into a Google Sheet.
// Set SHEETS_WEBAPP_URL on the flow tab -> Environment. Empty = branch does nothing.
const url = env.get('SHEETS_WEBAPP_URL');
if (!url) { return null; }

if (url.indexOf('/exec') === -1) {
    node.error('That URL does not end in /exec. The /dev URL only works for you, ' +
               'logged in, in a browser. Use Deploy > Manage deployments to get /exec.');
    return null;
}

const s = msg.student;
msg.url     = url;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    date:      msg.fmt.date,
    time:      msg.fmt.time,
    studentId: s.studentId,
    name:      s.name,
    className: s.className,
    uid:       msg.scan.uid,
    device:    msg.scan.device,
    direction: msg.tap.direction,
    status:    msg.tap.status
};

// Apps Script answers a POST with a 302 redirect. Node-RED would re-send the POST
// to the redirect target, which only accepts GET -- that is the "405" error.
// So we turn auto-following off and do the second hop ourselves.
msg.followRedirects = false;
return msg;

// ============================================================
//  The two 16-character lines the ESP32 prints, plus a status the
//  firmware turns into a distinct beep pattern.
// ============================================================
const s = msg.student;
let line1, line2;

switch (msg.result) {
    case 'in_ontime':
        line1 = 'Welcome!';
        line2 = s.name;
        break;
    case 'in_late':
        line1 = 'LATE ' + msg.fmt.time;
        line2 = s.name;
        break;
    case 'out':
        line1 = 'Goodbye!';
        line2 = s.name;
        break;
    case 'duplicate':
        line1 = 'Already Tapped';
        line2 = s ? s.name : msg.scan.uid;
        break;
    default:
        line1 = 'Unknown Card';
        line2 = msg.scan.uid;
}

msg.topic   = 'school/attendance/ack';
msg.payload = {
    status:    msg.result,
    uid:       msg.scan.uid,
    name:      s ? s.name : '',
    direction: msg.tap ? msg.tap.direction : '',
    line1:     String(line1).substring(0, 16),
    line2:     String(line2).substring(0, 16)
};
return msg;

// Unregistered card. Log the UID so you can copy it into students.json.
// Header: Date,Time,UID,Device
const q = function (v) {
    return '"' + String(v === null || v === undefined ? '' : v).replace(/"/g, '""') + '"';
};
msg.payload = [q(msg.fmt.date), q(msg.fmt.time), q(msg.scan.uid), q(msg.scan.device)].join(',');
return msg;

// Sends ONE test message, nothing else.
const TOKEN = env.get('TELEGRAM_BOT_TOKEN');
const CHAT  = env.get('TEST_CHAT_ID');
if (!TOKEN) { node.error('TELEGRAM_BOT_TOKEN is empty. Flow tab -> Environment.'); return null; }
if (!CHAT)  { node.error('TEST_CHAT_ID is empty. Flow tab -> Environment.');       return null; }

msg.url     = 'https://api.telegram.org/bot' + TOKEN + '/sendMessage';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { chat_id: CHAT, text: 'Test from Node-RED. Telegram is working.' };
return msg;

// Appends ONE test row to your Google Sheet, nothing else.
const url = env.get('SHEETS_WEBAPP_URL');
if (!url) { node.error('SHEETS_WEBAPP_URL is empty. Flow tab -> Environment.'); return null; }
if (url.indexOf('/exec') === -1) {
    node.error('That URL does not end in /exec. Use Deploy > Manage deployments.');
    return null;
}

msg.url     = url;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    date: '2026-09-19', time: '08:00:00', studentId: 'TEST', name: 'Test Row',
    className: 'Test', uid: 'TESTUID', device: 'node-red-test',
    direction: 'IN', status: 'ON_TIME'
};
msg.followRedirects = false;
return msg;

// Apps Script never answers a POST directly. It writes the row, then sends a 302
// pointing at script.googleusercontent.com where the reply is served.
// That address accepts GET only -- re-POSTing to it is what produced HTTP 405.
//
// Output 1 -> fetch the reply with GET.  Output 2 -> no redirect, pass straight on.
const REDIRECTS = [301, 302, 303, 307, 308];

if (REDIRECTS.indexOf(msg.statusCode) !== -1) {
    const loc = msg.headers && msg.headers.location;
    if (!loc) { node.error('Google sent a redirect with no Location header.'); return null; }
    node.status({ fill: 'blue', shape: 'dot', text: 'row sent, fetching reply' });
    msg.url     = loc;
    msg.payload = '';
    delete msg.headers;
    return [msg, null];
}
node.status({});
return [null, msg];

// Turns Google's HTML error pages into a plain-English cause.
const status = msg.statusCode;
const body   = (typeof msg.payload === 'string') ? msg.payload : JSON.stringify(msg.payload);

try {
    const out = JSON.parse(body);
    node.status({
        fill:  out.ok ? 'green' : 'red',
        shape: 'dot',
        text:  out.ok ? ('OK - wrote row ' + out.row) : ('script said: ' + out.error)
    });
    msg.payload = out;
    return msg;
} catch (e) {
    let why;
    if (/accounts\.google\.com|ServiceLogin|Sign in to continue/i.test(body)) {
        why = 'Google asked for a LOGIN, so your Web App is not public. ' +
              'Deploy > Manage deployments > pencil icon > Who has access = "Anyone" ' +
              '(NOT "Anyone with Google account") > Deploy.';
    } else if (/Request access|You need access|permission/i.test(body)) {
        why = 'Google says you need access. Same fix: Who has access = "Anyone".';
    } else if (/Script function not found|doPost/i.test(body)) {
        why = 'The script has no doPost function. Did you paste google-apps-script.gs and save?';
    } else {
        why = 'Not JSON, and not a page I recognise. Open your /exec URL in a ' +
              'PRIVATE/Incognito browser window - if it does not show {"ok":true} ' +
              'there, the problem is on the Google side, not in Node-RED.';
    }
    node.status({ fill: 'red', shape: 'dot', text: 'HTML back (HTTP ' + status + ')' });
    msg.payload = { ok: false, httpStatus: status, diagnosis: why,
                    firstBytes: body.substring(0, 160) };
    return msg;
}

// =====================================================================
//  THE CLOCK.
//
//  An arrival is an event. An absence is the ABSENCE of an event, so
//  nothing can trigger on it -- something has to look at the time and ask
//  "who is missing?". This node ticks every few seconds and fires each
//  check once per day, the moment its deadline passes.
//
//  A ticker rather than a fixed cron, because the deadlines are derived
//  from school-calendar.json. Change graceSeconds to 10 for a live demo
//  and the check follows automatically - no cron editing.
//
//  Out 1 -> absence roll call is due
//  Out 2 -> checkout roll call is due
// =====================================================================
const cal = global.get('calendar') || {};
if (!cal.classStart) {
    node.status({ fill: 'grey', shape: 'ring', text: 'calendar not loaded' });
    return null;
}

const START    = cal.classStart || '08:00';
const END      = cal.classEnd   || '13:00';
const GRACE    = (typeof cal.graceSeconds === 'number') ? cal.graceSeconds : 600;
const OUTGRACE = (typeof cal.checkoutGraceSeconds === 'number') ? cal.checkoutGraceSeconds : 1800;

const now = new Date();
const pad = function (n) { return String(n).padStart(2, '0'); };
const today = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());

// --- school day? -----------------------------------------------------
const schoolDays = cal.schoolDays || [1, 2, 3, 4, 5];
if (schoolDays.indexOf(now.getDay()) === -1) {
    node.status({ fill: 'grey', shape: 'ring', text: 'not a school day' });
    return null;
}
if ((cal.holidays || []).indexOf(today) !== -1) {
    node.status({ fill: 'grey', shape: 'ring', text: 'school holiday' });
    return null;
}

function atClock(hhmm) {
    const p = String(hhmm).split(':');
    const d = new Date(now.getTime());
    d.setHours(parseInt(p[0], 10) || 0, parseInt(p[1], 10) || 0, 0, 0);
    return d;
}

const absenceDue  = new Date(atClock(START).getTime() + GRACE * 1000);
const checkoutDue = new Date(atClock(END).getTime() + OUTGRACE * 1000);

const done = flow.get('checksDone') || {};

// A new day re-arms everything.
if (done.date !== today) {
    done.date       = today;
    done.absence    = false;
    done.checkout   = false;
    done.absenceDue = 0;
    done.checkoutDue = 0;
}

// Deadline moved? That means you edited school-calendar.json and clicked Load
// calendar -- almost always because you are setting up a demo. Re-arm that check.
//
// BUT only if the new deadline is still in the future. Editing the calendar at
// lunchtime must never re-send this morning's absence alerts to parents.
if (done.absenceDue !== absenceDue.getTime()) {
    done.absenceDue = absenceDue.getTime();
    if (now.getTime() < absenceDue.getTime()) { done.absence = false; }
}
if (done.checkoutDue !== checkoutDue.getTime()) {
    done.checkoutDue = checkoutDue.getTime();
    if (now.getTime() < checkoutDue.getTime()) { done.checkout = false; }
}

let fire = [null, null];

if (!done.absence && now.getTime() >= absenceDue.getTime()) {
    done.absence = true;
    fire[0] = { checkType: 'absence', today: today,
                cutoff: pad(absenceDue.getHours()) + ':' + pad(absenceDue.getMinutes()) +
                        ':' + pad(absenceDue.getSeconds()) };
}
if (!done.checkout && now.getTime() >= checkoutDue.getTime()) {
    done.checkout = true;
    fire[1] = { checkType: 'checkout', today: today,
                cutoff: pad(checkoutDue.getHours()) + ':' + pad(checkoutDue.getMinutes()) +
                        ':' + pad(checkoutDue.getSeconds()) };
}
flow.set('checksDone', done);

const waiting = [];
if (!done.absence)  { waiting.push('absence@' + pad(absenceDue.getHours()) + ':' + pad(absenceDue.getMinutes())); }
if (!done.checkout) { waiting.push('checkout@' + pad(checkoutDue.getHours()) + ':' + pad(checkoutDue.getMinutes())); }
node.status({ fill: 'blue', shape: 'ring',
              text: waiting.length ? ('waiting: ' + waiting.join(', '))
                                   : 'both done today - use the manual buttons' });

if (!fire[0] && !fire[1]) { return null; }
return fire;

// =====================================================================
//  ROLL CALL  -  runs for both checks.
//
//    checkType 'absence'  : who has no IN row today?
//    checkType 'checkout' : who has an IN but no OUT row today?
//
//  Reads attendance.csv rather than trusting memory, so a Node-RED
//  restart cannot make the whole school look absent.
//
//  Out 1 -> one message per student to chase
//  Out 2 -> one summary for the school office
// =====================================================================
const roster = global.get('students') || {};
const cal    = global.get('calendar')  || {};
const check  = msg.checkType || 'absence';
const today  = msg.today;
const cutoff = msg.cutoff || '';

function parseCsvLine(line) {
    const out = [];
    let cur = '', inQuotes = false;
    for (let i = 0; i < line.length; i++) {
        const c = line[i];
        if (inQuotes) {
            if (c === '"') {
                if (line[i + 1] === '"') { cur += '"'; i++; }
                else { inQuotes = false; }
            } else { cur += c; }
        } else {
            if (c === '"') { inQuotes = true; }
            else if (c === ',') { out.push(cur); cur = ''; }
            else { cur += c; }
        }
    }
    out.push(cur);
    return out;
}

// Columns: Date,Time,StudentID,Name,Class,UID,Device,Direction,Status
const csv = (typeof msg.payload === 'string') ? msg.payload : '';
const inAt = {}, outAt = {}, lateAt = {};
csv.split(/\r?\n/).forEach(function (line) {
    if (!line.trim()) { return; }
    const c = parseCsvLine(line);
    if (c.length < 8) { return; }
    if (c[0] !== today) { return; }
    const uid = c[5], dir = c[7], st = c[8];
    if (dir === 'IN')  { inAt[uid] = c[1]; if (st === 'LATE') { lateAt[uid] = c[1]; } }
    if (dir === 'OUT') { outAt[uid] = c[1]; }
});

const excusedToday = (cal.excused && cal.excused[today]) || [];
const rosterUids = Object.keys(roster).filter(function (k) { return k.charAt(0) !== '_'; });
const rosterCount = rosterUids.length;
const inCount  = Object.keys(inAt).length;
const outCount = Object.keys(outAt).length;

if (rosterCount === 0) {
    node.error('Roster is empty - students.json did not load. Nothing sent.');
    return null;
}

// --- SAFETY GUARD ----------------------------------------------------
// Nobody tapped at all? Far more likely the reader died than that the whole
// school is missing. Never message parents on that.
const observed = (check === 'absence') ? inCount : outCount;
if (observed === 0) {
    node.status({ fill: 'red', shape: 'dot', text: 'no ' + check + ' taps - parents NOT notified' });
    return [null, { payload: {
        checkType: check, date: today, aborted: true,
        reason: (check === 'absence')
            ? 'No arrivals were recorded at all today. The gate reader is probably ' +
              'offline. No parent was notified.'
            : 'No departures were recorded at all today. Either nobody has tapped out ' +
              'yet or the reader is offline. No parent was notified.',
        rosterCount: rosterCount, inCount: inCount, outCount: outCount
    }}];
}

// --- who are we chasing? ---------------------------------------------
const chase = [];
rosterUids.forEach(function (uid) {
    const s = roster[uid];
    if (excusedToday.indexOf(s.studentId) !== -1) { return; }

    if (check === 'absence') {
        if (inAt[uid]) { return; }                    // arrived
    } else {
        if (!inAt[uid]) { return; }                   // never arrived - not our problem here
        if (outAt[uid]) { return; }                   // already left
    }
    chase.push({
        uid: uid, studentId: s.studentId, name: s.name, className: s.className,
        parentChatId: s.parentChatId, arrivedAt: inAt[uid] || ''
    });
});

const minRatio   = (typeof cal.minPresentRatio === 'number') ? cal.minPresentRatio : 0.3;
const lowTurnout = (check === 'absence') && ((inCount / rosterCount) < minRatio);

if (check === 'absence') {
    global.set('absenceAlerted', {
        date: today,
        ids:  chase.map(function (a) { return a.studentId; })
    });
}

node.status({
    fill:  chase.length ? 'yellow' : 'green',
    shape: 'dot',
    text:  check + ': ' + chase.length + ' to chase'
});

const alerts = chase.map(function (a) {
    return { student: a, today: today, cutoff: cutoff, checkType: check, payload: {} };
});

const nameOf = function (uid) { return roster[uid] ? roster[uid].name : uid; };

const lateNames = Object.keys(lateAt).map(function (uid) {
    return nameOf(uid) + ' (' + lateAt[uid] + ')';
});

// Who the counts are actually made of. Printed in the summary so the numbers can
// always be checked against names, instead of having to open the CSV.
const arrivedList = Object.keys(inAt).sort().map(function (uid) {
    return nameOf(uid) + ' ' + inAt[uid];
});
const leftList = Object.keys(outAt).sort().map(function (uid) {
    return nameOf(uid) + ' ' + outAt[uid];
});

const summary = { payload: {
    checkType:   check,
    date:        today,
    cutoff:      cutoff,
    rosterCount: rosterCount,
    inCount:     inCount,
    outCount:    outCount,
    chaseCount:  chase.length,
    lowTurnout:  lowTurnout,
    late:        lateNames,
    arrivedList: arrivedList,
    leftList:    leftList,
    chase:       chase.map(function (a) { return a.name + ' (' + a.studentId + ')'; })
}};

return [alerts, summary];

// Message to ONE parent, for either check.
//
// Wording matters. It says we have no RECORD -- it does not assert where the
// child is, because a forgotten card looks identical to a real absence.
const TOKEN = env.get('TELEGRAM_BOT_TOKEN');
if (!TOKEN) { node.warn('TELEGRAM_BOT_TOKEN not set on this tab - nothing sent'); return null; }

const check = msg.checkType;

// Safety switch. Leave these "false" until you have watched the summaries for a
// few real days. Until then only the office is told.
const flagName = (check === 'absence') ? 'NOTIFY_PARENTS' : 'NOTIFY_NOT_CHECKED_OUT';
if (String(env.get(flagName)).toLowerCase() !== 'true') {
    node.status({ fill: 'blue', shape: 'ring', text: 'dry run (' + flagName + '=false)' });
    return null;
}

const s = msg.student;
if (!s.parentChatId) { node.warn('No parentChatId for ' + s.name); return null; }

const school  = env.get('SCHOOL_NAME') || 'school';
const contact = env.get('SCHOOL_CONTACT') || '';
const name    = s.name + ' (' + s.studentId + ')';
let text;

if (check === 'absence') {
    text = 'Attendance Notice\n\n' +
           'We have no record of ' + name + ' arriving at ' + school +
           ' as of ' + msg.cutoff + ' today, ' + msg.today + '.\n\n' +
           'If your child is absent for a reason already known to us, please ignore ' +
           'this message. Otherwise please contact the school office.';
} else {
    text = 'Still at school\n\n' +
           name + ' arrived at ' + (s.arrivedAt || 'an unrecorded time') +
           ' but has not been recorded leaving ' + school +
           ' as of ' + msg.cutoff + ' today.\n\n' +
           'This often just means the card was not tapped on the way out. ' +
           'Please contact the school office if you expected them home.';
}

if (contact) { text += '\n\n' + contact; }

msg.url     = 'https://api.telegram.org/bot' + TOKEN + '/sendMessage';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { chat_id: s.parentChatId, text: text };
return msg;

// Summary for the school office. Always sends, even on a dry run --
// a human should see the result either way.
const TOKEN = env.get('TELEGRAM_BOT_TOKEN');
const CHAT  = env.get('ADMIN_CHAT_ID');
if (!TOKEN || !CHAT) { node.warn('TELEGRAM_BOT_TOKEN or ADMIN_CHAT_ID not set'); return null; }

const p     = msg.payload;
const check = p.checkType;
let text;

if (p.aborted) {
    text = 'ATTENDANCE SYSTEM WARNING - ' + p.date + '\n\n' + p.reason;
} else if (check === 'absence') {
    const dry = String(env.get('NOTIFY_PARENTS')).toLowerCase() !== 'true';
    text = 'MORNING ROLL CALL  ' + p.date + '\n' +
           'cutoff ' + p.cutoff + '\n\n' +
           'Arrived: ' + p.inCount + ' of ' + p.rosterCount + '\n' +
           'Absent : ' + p.chaseCount + '\n';
    if (p.arrivedList && p.arrivedList.length && p.arrivedList.length <= 12) {
        text += '\nArrived:\n' +
                p.arrivedList.map(function (a) { return '- ' + a; }).join('\n') + '\n';
    }
    if (p.late.length) {
        text += '\nLate:\n' + p.late.map(function (a) { return '- ' + a; }).join('\n') + '\n';
    }
    if (p.chaseCount) {
        text += '\nNo record of arrival:\n' +
                p.chase.map(function (a) { return '- ' + a; }).join('\n') + '\n';
    }
    if (p.lowTurnout) {
        text += '\nNOTE: turnout is unusually low. Check the gate reader before acting.\n';
    }
    text += p.chaseCount === 0
        ? '\nFull attendance. Nothing to send.'
        : (dry ? '\n(Dry run - parents NOT messaged. Set NOTIFY_PARENTS=true when ready.)'
               : '\nParents of absent students have been notified.');
} else {
    const dry = String(env.get('NOTIFY_NOT_CHECKED_OUT')).toLowerCase() !== 'true';
    text = 'END OF DAY CHECK  ' + p.date + '\n' +
           'cutoff ' + p.cutoff + '\n\n' +
           'Arrived today : ' + p.inCount + '\n' +
           'Tapped out    : ' + p.outCount + '\n' +
           'Still on site : ' + p.chaseCount + '\n';
    // Counts come from EVERY row dated today, which includes earlier test runs.
    // Listing the names makes that obvious instead of surprising.
    if (p.arrivedList && p.arrivedList.length && p.arrivedList.length <= 12) {
        text += '\nArrived today:\n' +
                p.arrivedList.map(function (a) { return '- ' + a; }).join('\n') + '\n';
    }
    if (p.leftList && p.leftList.length && p.leftList.length <= 12) {
        text += '\nTapped out:\n' +
                p.leftList.map(function (a) { return '- ' + a; }).join('\n') + '\n';
    }
    if (p.chaseCount) {
        text += '\nNo record of leaving:\n' +
                p.chase.map(function (a) { return '- ' + a; }).join('\n') + '\n';
    }
    text += p.chaseCount === 0
        ? '\nEveryone who arrived has left. Nothing to send.'
        : (dry ? '\n(Dry run - parents NOT messaged. Set NOTIFY_NOT_CHECKED_OUT=true when ready.)'
               : '\nParents have been notified.');
}

msg.url     = 'https://api.telegram.org/bot' + TOKEN + '/sendMessage';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { chat_id: CHAT, text: text };
return msg;

// =====================================================================
//  DEMO RESET  -  wipe today and start the day over.
//
//  >>> THIS ERASES attendance.csv <<<  Everything logged today is lost.
//  It exists so a rehearsal starts from a clean slate. Do not press it on a
//  real school day.
//
//  It clears three things that otherwise carry over between demo runs:
//    attendance.csv      the roll call counts EVERY row dated today, so an
//                        earlier run's taps keep showing up in the totals
//    flow.todayTaps      per-student IN/OUT state, which decides whether the
//                        next tap is an arrival or a departure
//    global.absenceAlerted  who was reported absent, used for the correction
//                        message when they turn up late
// =====================================================================
flow.set('todayTaps', null);
flow.set('bounce', null);
global.set('absenceAlerted', null);

// Rewrite the CSV with just its header row. The file node below is set to
// OVERWRITE, not append.
msg.payload = 'Date,Time,StudentID,Name,Class,UID,Device,Direction,Status';

node.warn('DEMO RESET: attendance.csv erased and today\'s state cleared.');
node.status({ fill: 'red', shape: 'dot', text: 'today wiped' });
return msg;

// =====================================================================
//  FIND NEW PARENT CHAT IDs
//
//  Getting 30 parents to each install @userinfobot and read out a number
//  does not scale. Instead: give every parent the bot link, ask them to
//  press START and send any message. Then press this button and their
//  name and chat id appear below, ready to paste into students.json.
//
//  Telegram keeps un-read updates for 24 hours only, so collect them on
//  the day. Once read here they are consumed, which is why each id is
//  remembered - press the button twice and you still see everyone.
// =====================================================================
const TOKEN = env.get('TELEGRAM_BOT_TOKEN');
if (!TOKEN) {
    node.error('TELEGRAM_BOT_TOKEN is empty. Flow tab -> Environment.');
    return null;
}

const offset = flow.get('tgOffset') || 0;
msg.url = 'https://api.telegram.org/bot' + TOKEN + '/getUpdates?timeout=0' +
          (offset ? ('&offset=' + offset) : '');
msg.payload = '';
return msg;

// Pull the sender of every waiting message out of the getUpdates reply.
const r = msg.payload;

if (!r || typeof r !== 'object') {
    node.error('Telegram did not return JSON. Check the bot token.');
    return null;
}
if (!r.ok) {
    node.error('Telegram said: ' + (r.description || JSON.stringify(r)));
    return null;
}

const known = flow.get('knownChats') || {};
let offset  = flow.get('tgOffset') || 0;
const fresh = [];

(r.result || []).forEach(function (u) {
    if (u.update_id >= offset) { offset = u.update_id + 1; }

    const m = u.message || u.edited_message || u.channel_post || u.my_chat_member;
    if (!m || !m.chat) { return; }

    const chat = m.chat;
    const id   = String(chat.id);
    const name = [chat.first_name, chat.last_name].filter(Boolean).join(' ') ||
                 chat.title || chat.username || '(no name)';

    if (!known[id]) {
        known[id] = name;
        fresh.push({ chatId: id, name: name, username: chat.username || '' });
    }
});

flow.set('knownChats', known);
flow.set('tgOffset', offset);

// A block you can paste straight into students.json, one line per person.
const paste = fresh.map(function (c) {
    return '"parentChatId": "' + c.chatId + '",   // ' + c.name;
});

node.status({
    fill:  fresh.length ? 'green' : 'grey',
    shape: 'dot',
    text:  fresh.length ? (fresh.length + ' new') : ('no new (known: ' +
           Object.keys(known).length + ')')
});

msg.payload = {
    newContacts:  fresh,
    pasteIntoStudentsJson: paste,
    everyoneSoFar: known
};
return msg;
